contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 am, uint256 lockTime, uint256 minSum) public payable {
        c.SetMinSum(minSum);

        uint256 beforeBal = address(this).balance;
        c.Put{value: am}(lockTime);

        (uint256 unlockTimeBefore, uint256 balanceBefore) = c.Acc(address(this));
        require(balanceBefore == beforeBal + am, "Put did not credit balance");

        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }

        (uint256 unlockTimeAfter, uint256 balanceAfter) = c.Acc(address(this));

        bool expectedRevert = (balanceBefore < minSum) || (balanceBefore < am) || (block.timestamp <= unlockTimeBefore);

        assert(reverted == expectedRevert);
        assert(!reverted || balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

