contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address log, uint minSum, uint lockTime, uint amount, uint collectAm) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        require(collectAm <= amount, "collectAm too large for simple rule");

        c.SetLogFile(log);
        c.SetMinSum(minSum);
        c.Initialized();
        c.Put{value: amount}(lockTime);

        address sender = address(this);
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeUserBalance) = c.Acc(sender);

        bool reverted;
        try c.Collect(collectAm) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterUserBalance) = c.Acc(sender);
        uint afterContractBalance = address(c).balance;

        if (reverted) {
            assert(afterContractBalance == beforeContractBalance && afterUserBalance == beforeUserBalance);
        } else {
            assert(beforeUserBalance >= collectAm);
            assert(afterUserBalance == beforeUserBalance - collectAm);
            assert(afterContractBalance == beforeContractBalance - collectAm);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
