    }

    function run(uint256 val) public payable {
        require(true);

        bool reverted1;
        try c.SetMinSum(val) { reverted1 = false; } catch { reverted1 = true; }

        uint256 afterFirst = c.MinSum();

        if (!reverted1) {
            bool initReverted;
            try c.Initialized() { initReverted = false; } catch { initReverted = true; }
            require(!initReverted);

            bool reverted2;
            try c.SetMinSum(val + 1) { reverted2 = false; } catch { reverted2 = true; }

            uint256 afterSecond = c.MinSum();

            assert(reverted2 && afterSecond == afterFirst && afterFirst == val);
        } else {
            assert(false);
        }
    }

    receive() external payable {}
}

